mkuse!{use rustc_abi :: ExternAbi ;}
mkuse!{use rustc_ast :: InlineAsmOptions ;}
mkuse!{use rustc_middle :: mir :: * ;}
mkuse!{use rustc_middle :: span_bug ;}
mkuse!{use rustc_middle :: ty :: { self , TyCtxt , layout } ;}
mkuse!{use rustc_target :: spec :: PanicStrategy ;}
mkitem!{mkstruct!{# [doc = " A pass that runs which is targeted at ensuring that codegen guarantees about"] # [doc = " unwinding are upheld for compilations of panic=abort programs."] # [doc = ""] # [doc = " When compiling with panic=abort codegen backends generally want to assume"] # [doc = " that all Rust-defined functions do not unwind, and it's UB if they actually"] # [doc = " do unwind. Foreign functions, however, can be declared as \"may unwind\" via"] # [doc = " their ABI (e.g. `extern \"C-unwind\"`). To uphold the guarantees that"] # [doc = " Rust-defined functions never unwind a well-behaved Rust program needs to"] # [doc = " catch unwinding from foreign functions and force them to abort."] # [doc = ""] # [doc = " This pass walks over all functions calls which may possibly unwind,"] # [doc = " and if any are found sets their cleanup to a block that aborts the process."] # [doc = " This forces all unwinds, in panic=abort mode happening in foreign code, to"] # [doc = " trigger a process abort."] # [derive (PartialEq)] pub (super) struct AbortUnwindingCalls ;}}
mkitem!{mkimpl!{impl < 'tcx > crate :: MirPass < 'tcx > for AbortUnwindingCalls { fn run_pass (& self , tcx : TyCtxt < 'tcx > , body : & mut Body < 'tcx >) { let def_id = body . source . def_id () ; let kind = tcx . def_kind (def_id) ; if ! kind . is_fn_like () { return ; } let body_ty = tcx . type_of (def_id) . skip_binder () ; let body_abi = match body_ty . kind () { ty :: FnDef (..) => body_ty . fn_sig (tcx) . abi () , ty :: Closure (..) => ExternAbi :: RustCall , ty :: CoroutineClosure (..) => ExternAbi :: RustCall , ty :: Coroutine (..) => ExternAbi :: Rust , ty :: Error (_) => return , _ => span_bug ! (body . span , "unexpected body ty: {:?}" , body_ty) , } ; let body_can_unwind = layout :: fn_can_unwind (tcx , Some (def_id) , body_abi) ; for block in body . basic_blocks . as_mut () { let Some (terminator) = & mut block . terminator else { continue } ; let span = terminator . source_info . span ; if let TerminatorKind :: UnwindResume = & terminator . kind && ! body_can_unwind { terminator . kind = TerminatorKind :: UnwindTerminate (UnwindTerminateReason :: Abi) ; } if block . is_cleanup { continue ; } let call_can_unwind = match & terminator . kind { TerminatorKind :: Call { func , .. } => { let ty = func . ty (& body . local_decls , tcx) ; let sig = ty . fn_sig (tcx) ; let fn_def_id = match ty . kind () { ty :: FnPtr (..) => None , & ty :: FnDef (def_id , _) => Some (def_id) , _ => span_bug ! (span , "invalid callee of type {:?}" , ty) , } ; layout :: fn_can_unwind (tcx , fn_def_id , sig . abi ()) } TerminatorKind :: Drop { .. } => { tcx . sess . opts . unstable_opts . panic_in_drop == PanicStrategy :: Unwind && layout :: fn_can_unwind (tcx , None , ExternAbi :: Rust) } TerminatorKind :: Assert { .. } | TerminatorKind :: FalseUnwind { .. } => { layout :: fn_can_unwind (tcx , None , ExternAbi :: Rust) } TerminatorKind :: InlineAsm { options , .. } => { options . contains (InlineAsmOptions :: MAY_UNWIND) } _ if terminator . unwind () . is_some () => { span_bug ! (span , "unexpected terminator that may unwind {:?}" , terminator) } _ => continue , } ; if ! call_can_unwind { let cleanup = block . terminator_mut () . unwind_mut () . unwrap () ; * cleanup = UnwindAction :: Unreachable ; } else if ! body_can_unwind && matches ! (terminator . unwind () , Some (UnwindAction :: Continue)) { let cleanup = block . terminator_mut () . unwind_mut () . unwrap () ; * cleanup = UnwindAction :: Terminate (UnwindTerminateReason :: Abi) ; } } super :: simplify :: remove_dead_blocks (body) ; } fn is_required (& self) -> bool { true } }}}